<script setup>
import {ref,computed} from 'vue';
const props=defineProps({subjects:Array,modelValue:Array}),emit=defineEmits(['update:modelValue']),search=ref('');
const visible=computed(()=>props.subjects.filter(s=>s.toLowerCase().includes(search.value.toLowerCase())));
function toggle(value,checked){emit('update:modelValue',checked?[...new Set([...props.modelValue,value])]:props.modelValue.filter(x=>x!==value))}
</script><template><fieldset class="compact-subjects"><legend>Subjects</legend><label v-if="subjects.length>6">Search subjects<input v-model="search" type="search" placeholder="Find a subject"></label><div class="row subject-selection"><small>{{modelValue.length}} selected</small><div><button type="button" class="plain" @click="emit('update:modelValue',[...subjects])">All</button><button type="button" class="plain" @click="emit('update:modelValue',[])">Clear</button></div></div><div class="subject-checks"><label v-for="s in visible" :key="s" class="check" :class="{selected:modelValue.includes(s)}"><input type="checkbox" :checked="modelValue.includes(s)" @change="toggle(s,$event.target.checked)"><span>{{s}}</span></label></div><p v-if="!visible.length" role="status">No matching subjects.</p></fieldset></template>
